const INTERVAL=3e3;let currentSlide=0;const images=document.querySelectorAll(".slide");export default function Slider(){setInterval(initSlider,3e3)}function initSlider(){currentSlide=(currentSlide+1)%images.length,slideNext()}function slideNext(){images.forEach((e=>{e.style.transform=`translateX(-${100*currentSlide}%)`}))}